import React, { Component } from 'react';
import './ControllerDisplay.css';

const LETTERS = ['L', 'R', 'U', 'D', 'Z', 'X'];

export default class ControllerDisplay extends Component {
  render() {
    return <div className='display-box' onClick={this.props.onClick}>
      {LETTERS.map(
        (l, i) =>
        <div
          className={`
            tick
            ${(Math.pow(2, i) & this.props.controller) ? 'ticked' : ''}
            ${this.props.selected ? 'selected' : ''}
           `
          }
        />
        )}
    </div>;
  }
}
